            case BandCount::B8:   return eightBand();
            case BandCount::B10:  return tenBand();
            case BandCount::B16:  return sixteenBand();
            case BandCount::B31:  return thirdOctave();
            case BandCount::B124: return ultra124();
        }
        return tenBand();
    }
};

